const runtime = { serverBaseUrl, home: os.homedir(), uid: process.getuid(), gid: process.getgid(), ...(process.env.PI_CODING_AGENT_DIR ? { piAgentDirs: [path.relative(os.homedir(), process.env.PI_CODING_AGENT_DIR)] } : {}) };
